"""The per-run context handed to command handlers, and the exceptions that steer the exit status."""

import os
import sys

from tallybook.cli.framework import UsageError  # noqa: F401  (re-exported)
from tallybook.errors import NotFoundError, ValidationError

STDIN_NAME = "standard input"


class Context:
    """What a handler may use: buffered output, the book, files and "today"."""

    stdin_name = STDIN_NAME

    def __init__(self, db_path, today_arg=None):
        self.db_path = db_path
        self.today_arg = today_arg
        self.exit_status = 0
        self._stdout = []
        self._stderr = []

    @property
    def today(self):
        """``--today`` or the real date."""
        if self.today_arg is not None:
            return self.today_arg
        import datetime

        return datetime.date.today()

    def out(self, text):
        self._stdout.append(text)

    def err(self, text):
        self._stderr.append(text)

    def stdout_text(self):
        return "".join(self._stdout)

    def stderr_text(self):
        return "".join(self._stderr)

    def open_store(self):
        """Open the existing book (never creates one)."""
        from tallybook.storage import Store

        if not os.path.lexists(self.db_path):
            raise NotFoundError("no such database: %s (run `tallybook init`)" % self.db_path)
        return Store.open(self.db_path)

    def read_text(self, path, what="file"):
        """The text of a UTF-8 file; ``-`` is standard input."""
        if path == "-":
            return self._read_stdin()
        try:
            with open(path, "rb") as handle:
                data = handle.read()
        except OSError as exc:
            raise ValidationError("cannot read %s %s: %s" % (what, path, exc.strerror or exc))
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError:
            raise ValidationError("%s is not valid UTF-8 text" % path)

    def _read_stdin(self):
        stream = sys.stdin
        try:
            if hasattr(stream, "buffer"):
                data = stream.buffer.read()
            else:
                data = stream.read()
        except OSError as exc:
            raise ValidationError("cannot read %s: %s" % (STDIN_NAME, exc.strerror or exc))
        if isinstance(data, str):
            return data
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError:
            raise ValidationError("%s is not valid UTF-8 text" % STDIN_NAME)

